import{c as r,Q as t,j as s,m as a}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Cold-Start Anti-Patterns and Refactorings in Serverless Systems: An Empirical Study","description":"","frontmatter":{"url":"https://arxiv.org/abs/2512.16066","title":"Cold-Start Anti-Patterns and Refactorings in Serverless Systems: An Empirical Study","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2512.16066,"authors":["Syed Salauddin Mohammad Tariq","Foyzul Hassan","Amiangshu Bosu","Probir Roy (University of Michigan–Dearborn","Wayne State)"],"pdf_path":"pdfs/2512.16066.pdf","published_date":"2025-12-18T00:00:00.000Z","venue":"IEEE SANER 2026 (accepted, preprint)"},"headers":[],"relativePath":"research/papers/2025-12-19-cold-start-antipatterns-serverless-2512-16066.md","filePath":"research/papers/2025-12-19-cold-start-antipatterns-serverless-2512-16066.md","lastUpdated":1785909234000}'),n={name:"research/papers/2025-12-19-cold-start-antipatterns-serverless-2512-16066.md"};function i(o,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="cold-start-anti-patterns-and-refactorings-in-serverless-systems" tabindex="-1">Cold-Start Anti-Patterns and Refactorings in Serverless Systems <a class="header-anchor" href="#cold-start-anti-patterns-and-refactorings-in-serverless-systems" aria-label="Permalink to &quot;Cold-Start Anti-Patterns and Refactorings in Serverless Systems&quot;">​</a></h1><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><p>與多數視 cold-start 為黑盒最佳化的前作不同，本文把 cold start 當作 <strong>developer-visible design problem</strong>（開發者可見的設計問題）。從 <strong>81 個 adjudicated issue reports</strong>（跨開源 serverless 專案）推導初始化反模式的分類學（taxonomy），涵蓋 design / packaging / runtime 三層。</p><h2 id="商業動機-關鍵引用" tabindex="-1">商業動機（關鍵引用） <a class="header-anchor" href="#商業動機-關鍵引用" aria-label="Permalink to &quot;商業動機（關鍵引用）&quot;">​</a></h2><ul><li><strong>Amazon：每多 100ms 延遲 → 損失 1% 銷售</strong></li><li><strong>Google：回應時間增至 500ms → 搜尋流量降 20%</strong></li><li>冷啟動延遲源自跨多抽象層（import graphs → packaging → runtime → environment）</li></ul><h2 id="反模式分類-developer-visible-performance-而非-correctness-缺陷" tabindex="-1">反模式分類（developer-visible，performance 而非 correctness 缺陷） <a class="header-anchor" href="#反模式分類-developer-visible-performance-而非-correctness-缺陷" aria-label="Permalink to &quot;反模式分類（developer-visible，performance 而非 correctness 缺陷）&quot;">​</a></h2><ol><li><strong>Redundant library imports</strong>（冗餘 library 匯入）</li><li><strong>Deferred one-time initialization</strong>（一次性初始化未前置/未快取）</li><li><strong>Unnecessary packaging of large dependencies</strong>（大型相依不必要打包）</li></ol><h2 id="工具與成果" tabindex="-1">工具與成果 <a class="header-anchor" href="#工具與成果" aria-label="Permalink to &quot;工具與成果&quot;">​</a></h2><ul><li><strong>SCABench</strong>：可重現 benchmark</li><li><strong>InitScope</strong>：輕量分析框架，連結「what code is <em>loaded</em>」與「what is <em>executed</em>」</li><li>InitScope 定位準確度 <strong>提升 40%</strong>，診斷工作量 <strong>減少 64%</strong>（vs prior tools）</li></ul><h2 id="對-cc-workspace-的遷移啟示-直接對應" tabindex="-1">對 cc-workspace 的遷移啟示（直接對應） <a class="header-anchor" href="#對-cc-workspace-的遷移啟示-直接對應" aria-label="Permalink to &quot;對 cc-workspace 的遷移啟示（直接對應）&quot;">​</a></h2><ul><li><strong>Redundant imports</strong> → 18 個 hook scripts 中，每次工具呼叫都 spawn 的 hook（block-dangerous.sh 53ms/call）= 重複 init 成本</li><li><strong>Deferred one-time init</strong> → session-init.sh 592ms（含 git fetch）應快取 / 前置 / async</li><li><strong>InitScope「loaded vs executed」</strong> → auto-load 16,927 bytes 中有多少在每個 session 真正被引用？= 本研究 gap-map 同精神</li><li>核心遷移：<strong>冷啟動是可被靜態分析與重構的設計問題</strong>，不是不可控的固定成本</li></ul>',11)])])}const m=r(n,[["render",i]]);export{h as __pageData,m as default};
